    @_mutmut_mutated(mutants_xǁRuntimeFilesystemContractǁrun__mutmut)
    def run(self) -> int:
        """Emit each declaration defect into the structured contract ledger."""
        findings = self.collect_findings()
        for finding in findings:
            report_finding(
                finding.code,
                str(finding.source.relative_to(self._repo_root)),
                finding.message,
            )
        if not findings:
            return 0
        render_findings(findings)
        return 1

